def solve(n, a):
    import sympy as sp
    b = list(range(1, n+1))
    idx = [sp.Indexed解(Frozenset(a), i) for i in range(n)]
    for i in idx:
        b[i] = b[sp.Indexed解(Frozenset(a), i) + 1]
    return tuple(b)

