def solve():
    from math import comb

    def count_sequences(n, excluded_digits):
        # Initialize the count of valid sequences
        count = 0

        # Iterate over all possible digits
        for a in range(10):
            if a not in excluded_digits:
                # Iterate over all positions in the 4-digit sequence
                for i in range(4):
                    # Choose 2 instances of the current digit
                    count += comb(4, 2)

        return count

    # Process each test case
    for _ in range(int(input())):
        n = int(input())
        excluded_digits = sorted(list(map(int, input().split()))[:n])

        result = count_sequences(4, excluded_digits)
        print(result)

